#include "SourceInvestigation.h"
#include "ObjectCatalog.h"
#include <fstream>
#include <iostream>
#include <set>
#include <stop_token>
#include <stdexcept>
using namespace dft::sequential;
namespace ob=dft::objects;
static unsigned n=0;
static void need(bool v,const char* s){++n;if(!v)throw std::runtime_error(s);}
static void bad(const auto& r,const char* s){need(!r&&r.error().code==hier::ErrorCode::BadRequest,s);}
static std::string read(const std::string& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
static auto open(const char* file,const char* top){hier::model::OpenOptions o;o.files={file};o.tops={top};auto r=hier::Design::open(o);need(r.ok(),"open");return std::move(r.value());}
int main(int argc,char** argv){try{
 need(argc==3,"two own fixtures");auto d=open(argv[1],"W_tree");SourceInvestigationRequest r;r.statistics.scope="W_tree";r.statistics.recursive=true;r.scenarios.common.resolveLogic=true;r.scenarios.scenarios={{"A",{{{"W_tree.mode",0},false}}},{"B",{{{"W_tree.mode",0},true}}},{"C",{{{"W_tree.mode",0},false}}}};
 auto all=investigateRegisterSources(*d,r);need(all.ok()&&all->excerpts.complete,"bundle complete");auto s=registerStatistics(*d,r.statistics);auto rr=expandRegisterSourceHierarchyRanges(*d,*s,r.scenarios,r.ranges);auto q=selectRegisterSourceHierarchyRanges(*rr,r.query,r.selection);auto e=explainRegisterSourceSelection(*s,*rr,*q,r.evidence);auto l=locateSourceEvidence(*d,*e,r.locations);auto x=readSourceEvidenceExcerpts(*d,*l,r.excerpts);need(x.ok()&&x->complete,"original stage chain");need(all->statistics.snapshot.snapshotId==s->snapshot.snapshotId&&all->statistics.facts.size()==s->facts.size()&&all->ranges.rows==rr->rows&&all->selection.rows.size()==q->rows.size(),"same producers");need(all->evidence.facts.size()==e->facts.size()&&all->evidence.rows.size()==e->rows.size(),"same evidence domain");
 for(size_t i=0;i<e->facts.size();++i){auto& a=all->evidence.facts[i];auto& b=e->facts[i];need(a.fact==b.fact&&a.info.ref==b.info.ref&&a.info.process==b.info.process&&a.info.bits.lsb==b.info.bits.lsb&&a.info.bits.width==b.info.bits.width,"original fact dictionary index/identity");auto link=all->statistics.facts.at(a.fact);auto raw=all->statistics.pages.at(link.page).response.result.items.at(link.item);need(raw.ref==a.info.ref&&raw.process==a.info.process,"indices resolve within bundle");}
 need(all->locations.locations.size()==l->locations.size()&&all->excerpts.rows.size()==x->rows.size()&&all->excerpts.snippets.size()==x->snippets.size(),"same source domains");for(size_t i=0;i<x->snippets.size();++i){auto& a=all->excerpts.snippets[i];auto& b=x->snippets[i];need(a.file==b.file&&a.startOffset==b.startOffset&&a.endOffset==b.endOffset&&a.startLine==b.startLine&&a.text==b.text,"same owned original bytes");}
 std::stop_source stop;stop.request_stop();auto invalid=r;invalid.statistics.scope="";auto c=investigateRegisterSources(*d,invalid,stop.get_token());need(!c&&c.error().code==hier::ErrorCode::Cancelled,"pre-cancel priority");bad(investigateRegisterSources(*d,invalid),"explicit scope");
 for(int i=0;i<8;++i){auto z=r;z.statistics.scope="does_not_exist";switch(i){case 0:z.statistics.maxFacts=0;break;case 1:z.scenarios.common.resolveLogic=false;break;case 2:z.ranges.maxRows=0;break;case 3:z.query.scenario=0;break;case 4:z.selection.maxRows=0;break;case 5:z.evidence.maxFacts=0;break;case 6:z.locations.maxLocations=0;break;case 7:z.excerpts.maxBytes=0;break;}bad(investigateRegisterSources(*d,z),"validate every section before missing scope lookup");}
 for(int i=0;i<6;++i){auto z=r;switch(i){case 0:z.statistics.maxFacts=1;break;case 1:z.ranges.maxRows=1;break;case 2:z.selection.maxRows=1;break;case 3:z.evidence.maxFacts=1;break;case 4:z.locations.maxLocations=1;break;case 5:z.excerpts.maxBytes=1;break;}auto p=investigateRegisterSources(*d,z);need(p.ok()&&!p->excerpts.complete,"per-stage partial keeps bundle");}
 auto missing=r;missing.statistics.scope="does_not_exist";auto m=investigateRegisterSources(*d,missing);need(!m&&m.error().code==hier::ErrorCode::NotFound,"original scope error");need(investigateRegisterSources(*d,r)->excerpts.complete,"reuse after errors");
 auto raw=read(l->locations[0].span->path);auto bpos=raw.find("\r\n");need(bpos!=std::string::npos,"own CRLF source");auto badloc=*l;badloc.locations[0].span->start.offset=bpos+1;bad(readSourceEvidenceExcerpts(*d,badloc),"CRLF internal start");badloc=*l;bpos=raw.find("\r\n",badloc.locations[0].span->start.offset);need(bpos!=std::string::npos,"later CRLF");badloc.locations[0].span->end.offset=bpos+1;bad(readSourceEvidenceExcerpts(*d,badloc),"CRLF internal end");d.reset();need(!all->evidence.facts[0].info.process.empty()&&!all->excerpts.snippets[0].text.empty(),"bundle owns after Design release");
 auto cd=open(argv[2],"K_top");ob::CatalogRequest cr;cr.scope="K_top";cr.recursive=true;auto cat=ob::enumerateObjects(*cd,cr);need(cat.ok()&&cat->complete&&cat->instances.size()==7&&cat->objects.size()==60,"handwritten 7 instances/21 ports/32 signals");
 std::vector<hier::model::InstInfo> queue=cd->roots();std::vector<std::pair<ob::Kind,std::string>> expected;for(size_t k=0;k<queue.size();++k){const auto in=queue[k];need(cat->instances.at(k).info.ref==in.ref&&cat->instances.at(k).info.path==in.path,"Core BFS child-slot identity");expected.push_back({ob::Kind::Instance,in.ref});auto ports=cd->ports(in.ref);need(ports.ok(),"Core ports");for(auto& p:*ports)expected.push_back({ob::Kind::Port,p.ref});hier::PageRequest page;page.limit=2;do{auto sig=cd->signals(in.ref,page);need(sig.ok(),"Core signals pages");for(auto& v:sig->items)expected.push_back({ob::Kind::Signal,v.ref});page.cursor=sig->next;}while(!page.cursor.empty());page.cursor.clear();do{auto ch=cd->children(in.ref,page);need(ch.ok(),"Core children pages");queue.insert(queue.end(),ch->items.begin(),ch->items.end());page.cursor=ch->next;}while(!page.cursor.empty());}
 need(expected.size()==cat->objects.size(),"all Core objects exactly once");std::set<std::string> refs;for(size_t i=0;i<expected.size();++i){auto& v=cat->objects[i];need(v.kind==expected[i].first&&v.object.ref==expected[i].second&&refs.insert(v.object.ref).second,"original order/distinct identity");auto rawobj=cd->object(v.object.ref);need(rawobj.ok()&&v.object.pathText==rawobj->pathText&&v.object.name==rawobj->name&&v.object.inst==rawobj->inst,"original ObjectInfo");need(v.instance<cat->instances.size(),"owner dictionary index");if(v.port)need(v.port->ref==v.object.ref,"port ref");if(v.signal)need(v.signal->ref==v.object.ref,"signal ref");}
 auto exact=cr;exact.limits.maxObjects=60;need(ob::enumerateObjects(*cd,exact)->complete,"exact object cap");auto small=cr;small.limits.maxObjects=5;auto pref=ob::enumerateObjects(*cd,small);need(pref.ok()&&!pref->complete&&pref->objects.size()==5,"whole object prefix");for(size_t i=0;i<5;++i)need(pref->objects[i].object.ref==cat->objects[i].object.ref,"prefix unchanged");small=cr;small.limits.pageSize=1;auto pages=ob::enumerateObjects(*cd,small);need(pages.ok()&&pages->complete&&pages->objects.size()==60,"small pages");for(size_t i=0;i<60;++i)need(pages->objects[i].object.ref==cat->objects[i].object.ref,"page size preserves order");
 small=cr;small.text="*";small.limits.maxObjects=1;auto none=ob::enumerateObjects(*cd,small);need(none.ok()&&none->complete&&none->objects.empty()&&none->instances.size()==7,"literal text doesn't filter traversal");small=cr;small.kinds={};bad(ob::enumerateObjects(*cd,small),"empty kinds");small.kinds={ob::Kind::Port,ob::Kind::Port};bad(ob::enumerateObjects(*cd,small),"duplicate kinds");small.kinds={static_cast<ob::Kind>(99)};bad(ob::enumerateObjects(*cd,small),"invalid enum");small=cr;small.text=std::string(1,char(0xff));bad(ob::enumerateObjects(*cd,small),"invalid scalar UTF8");small=cr;small.text=std::string("a\0b",3);bad(ob::enumerateObjects(*cd,small),"NUL text");small=cr;small.limits.maxQueries=2;bad(ob::enumerateObjects(*cd,small),"query minimum");auto cc=ob::enumerateObjects(*cd,small,stop.get_token());need(!cc&&cc.error().code==hier::ErrorCode::Cancelled,"catalog cancellation priority");small=cr;small.scope="K_top.a";bad(ob::enumerateObjects(*cd,small),"non-instance or ambiguous scope");small=cr;small.scope="does_not_exist";auto notfound=ob::enumerateObjects(*cd,small);need(!notfound&&notfound.error().code==hier::ErrorCode::NotFound,"scope not found");need(ob::enumerateObjects(*cd,cr)->complete,"catalog reusable after errors");cd.reset();need(cat->objects[0].object.pathText=="K_top"&&cat->instances[0].info.name=="K_top","catalog owns after Design release");
 std::cout<<"{\"passed\":true,\"assertions\":"<<n<<"}\n";return 0;
}catch(const std::exception& e){std::cerr<<"after "<<n<<" assertions: "<<e.what()<<'\n';return 1;}}
